class Tentacle {
	constructor(r = null, x = null, y = null, c = null) {
		this.x0 = (x !== null) ? x : width/2;
		this.y0 = (y !== null) ? y : height/2;
		this.r0 = (r !== null) ? r : random(10, max(width, height)/10);
		this.c = c || color("silver");
		this.a0 = random(TAU);
		this.f = 0.1;
		this.n = random(111, 98765432);
		this.init();
	}

	init() {
		this.x = this.x0;
		this.y = this.y0;
		this.r = this.r0;
		this.a = this.a0;
		this.i = 1;
	}

	update() {
		if (this.r < 1) return true;

		this.r -= 0.15;
		this.i += 0.05;
		this.a += (noise(this.n + this.i, frameCount/63)-0.5)*PI/10; // random(-PI/10, PI/10);
		this.x += cos(this.a) * this.r * this.f;
		this.y += sin(this.a) * this.r * this.f;

		return false;
	}

	show() {
		push();

		if (this.r >= 1) {
			fill(this.c);
			circle(this.x, this.y, this.r*2)
		}
		/*
		while(this.r >= 1) {
			circle(this.x, this.y, this.r*2)
			this.update();
		}	
		*/
		pop();
	}
}

