let tentacles;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(2, 2, 12);
	stroke(2, 2, 12);
	strokeWeight(0.75);
	frameRate(60);

	tentacles = [];
	const num = (width + height) / 50;
	for (let i = 0; i < num; i++) {
		const x = random(width);
		const y = random(height);
		const c = color(random(300), random(300), random(300));
		tentacles.push(new Tentacle(25, x, y, c));
	}
}

function draw() {
	// background(2, 2, 12);

	if (true) {
		for (const t of tentacles) {
			t.show();
			t.update();
		}
		return; 
	}

	for (const t of tentacles) {
		t.init();
	}

	let finished = false;
	while(!finished) {
		finished = true;
		for (const t of tentacles) {
			t.show();
			finished = finished && t.update();
		}
	}
}

function mousePressed() {
	setup();
}
